/* UNIT I – Fundamentals of Robotics, Sensors and Instrumentation (content follows the course notes, Sections 1.1–1.18) */
(function () {
  const RIL = window.RIL, R = String.raw, T = RIL.table;
  RIL.units.push({
    n: 1, roman: 'I', title: 'Fundamentals of Robotics, Sensors and Instrumentation',
    desc: 'What a robot is and how it is built, classified and described; the sensors that make it observable; and the static and dynamic characteristics of the measurement systems that carry those signals.',
    syllabus: 'Introduction to robotics and automation, robot anatomy, classification, configurations, degrees of freedom, work envelope and coordinate systems. Sensors and transducers for position, displacement, velocity, acceleration, force, torque and proximity measurement. Measurement systems, static and dynamic characteristics, accuracy, precision, sensitivity, resolution, uncertainty and loading effects. Temperature, pressure, force and strain measurement.',
    topics: [
      {
        id: 'u1t1', n: 1, title: 'Introduction to Robotics and Automation', refs: 'Section 1.1 (1.1.1–1.1.6), Table 1.2',
        blurb: 'Definitions of robot and robotics, the three types of automation, why robots are used and where.',
        intro: 'The word <i>robot</i> comes from the Czech <i>robota</i> (forced labour). The first industrial robot, the Unimate, unloaded hot die-castings at General Motors in 1961; today robots weld, paint, assemble, palletise and increasingly work beside people as collaborative robots. This topic fixes the vocabulary used in the rest of the course.',
        objectives: ['State the ISO 8373 definition of an industrial robot and its three distinguishing properties.', 'Distinguish fixed, programmable and flexible automation by principle, volume/variety and investment.', 'List the advantages, limitations and principal applications of industrial robots.', 'Explain the relationship between robotics and automation.'],
        theory: `<p><b>Robot.</b> ISO 8373 defines an industrial robot as an “automatically controlled, reprogrammable, multipurpose manipulator, programmable in three or more axes, which can be either fixed in place or mobile for use in industrial automation applications”. Three properties separate a robot from other machines: <b>reprogrammability</b> (motions can be changed without physical alteration), <b>multipurpose</b> use (a new task by reprogramming and/or new tooling) and <b>multiple axes</b> (at least three independently controlled axes). <b>Robotics</b> is the interdisciplinary science of designing, building, sensing and controlling such machines.</p>
          <p><b>Automation</b> is the use of control systems to operate equipment with minimal human intervention. It is divided into three classes according to the trade-off between production volume and product variety (Table 1.2):</p>
          ${T(['', 'Fixed (hard)', 'Programmable', 'Flexible'], [['Principle', 'Sequence of operations fixed by equipment configuration', 'Sequence controlled by a program; changed between batches', 'Program and tooling changed with negligible changeover time'], ['Volume / variety', 'Very high volume, single product', 'Medium volume, batches of different products', 'Medium volume, mix of products produced continuously'], ['Investment', 'Very high for custom equipment', 'High for general-purpose equipment', 'High for system integration'], ['Examples', 'Transfer lines, bottling lines', 'CNC machines, industrial robots, PLC systems', 'Flexible manufacturing systems, robotic workcells']])}
          <p><b>Robotics and automation.</b> Robots belong to programmable and flexible automation: the same arm can be reprogrammed for a new product, whereas a transfer line is fixed automation. A robot is therefore one building block of an automated system, together with PLCs, conveyors, sensors and vision (Unit IV).</p>
          <p><b>Why robots?</b> Consistent quality and repeatability of the order of ±0.02 mm to ±0.1 mm; work in hazardous, hot, toxic or monotonous environments; high productivity through continuous operation; flexibility; and data for quality traceability. <b>Limitations:</b> high initial cost and integration effort, skilled programming and maintenance, limited dexterity and judgement in unstructured tasks, safety requirements (ISO 10218, ISO/TS 15066) and social concerns about job displacement. Robots are often grouped in generations: playback, sensor-based and intelligent.</p>`,
        principle: '<p>An automated cell is a closed loop of <b>measurement → decision → actuation</b>. Sensors report the state of parts and machines, a controller (PLC or robot controller) decides, and actuators (motors, cylinders, robots) act. Moving from manual to fully automated operation transfers each of these three functions from a person to equipment; collaborative operation shares the workspace again under safety monitoring.</p>',
        diagram: RIL.svgChain([['Manual', 'people do every task'], ['Semi-automated', 'machine + operator'], ['Fixed automation', 'dedicated line'], ['Programmable / flexible', 'robots, CNC, PLC'], ['Collaborative', 'cobot beside people']], { id: 'u1t1', label: 'levels of automation' }), diagramCaption: 'Levels of automation compared in the simulation (the cycle times used there are illustrative teaching values).',
        sims: ['automation-levels'], simIntro: 'Switch between automation levels. In Automatic mode the product changes every batch: fixed automation is fastest but pays a long changeover; robots keep flexibility. In the collaborative cell move the operator towards the cobot.',
        applications: ['Material handling: pick-and-place, palletising, machine loading.', 'Processing: spot and arc welding, painting, gluing, grinding, deburring.', 'Assembly of electronics and automotive sub-assemblies; vision-guided inspection.', 'Non-industrial: surgical, warehouse, agricultural, space robots and exoskeletons.'],
        observations: ['Fixed automation has the shortest cycle but the throughput collapses when product variety forces frequent changeovers.', 'A robot cell trades a little speed for very short changeovers, which is why robots dominate medium-volume, high-mix production.', 'Collaborative operation reduces robot speed when a person is near: safety, not motor power, limits its productivity.'],
        questions: [{ q: 'State the three properties in the ISO 8373 definition that separate a robot from other machines.', a: 'Reprogrammability, multipurpose use and at least three independently programmable axes.' }, { q: 'Classify a bottling line, a CNC machine centre and a robotic workcell producing a product mix.', a: 'Fixed (hard), programmable, flexible automation respectively.' }, { q: 'Why is a robot preferred to a transfer line for medium-volume production of several variants?', a: 'Because changeover is by reprogramming and tooling change with negligible time, whereas a transfer line must be physically rebuilt.' }],
        summary: 'An industrial robot is a reprogrammable, multipurpose manipulator with three or more axes. It is the key element of programmable and flexible automation, chosen for repeatability, safety in hazardous tasks and flexibility.'
      },
      {
        id: 'u1t2', n: 2, title: 'Robot Anatomy', refs: 'Section 1.2 (1.2.1–1.2.5), Fig. 1.1–1.3, Table 1.3, Eq. (1.1)',
        blurb: 'Base, links, joints, shoulder, elbow, wrist, end effector and the actuation system of a six-axis arm.',
        intro: 'A robot is not just an arm. The robot system comprises the manipulator, end-effector, actuators and drives, sensors, controller and teach pendant. This topic names the parts of the manipulator and the variables that describe its configuration.',
        objectives: ['Identify the components of a robot system and of a six-axis manipulator.', 'Distinguish links and joints and define the joint variable of revolute and prismatic joints.', 'Explain why joints 1–3 position the wrist and joints 4–6 orient the tool.', 'Interpret payload, reach, repeatability and accuracy specifications.'],
        theory: `<p><b>Robot system.</b> (1) <b>Manipulator</b> – links connected by joints with transmissions (gears, belts, harmonic drives, ball screws); (2) <b>end-effector</b> – gripper or tool on the wrist flange, task specific; (3) <b>actuators and drives</b> – servo, stepper or BLDC motors, pneumatic or hydraulic cylinders with their power amplifiers; (4) <b>sensors</b> – internal (joint encoders, motor current) and external (force, vision, proximity); (5) <b>controller</b> – computes trajectories and closes servo loops; (6) <b>teach pendant</b> and programming interface.</p>
          <p><b>Anatomy.</b> The manipulator is a chain of rigid links connected by joints. The fixed link is the <b>base</b> (link 0). In the anthropomorphic terminology of Fig. 1.2: the <b>waist/trunk</b> (joint 1) rotates about the vertical axis; the <b>shoulder</b> (joint 2) and <b>elbow</b> (joint 3) are horizontal axes carrying the <b>upper arm</b> (link 2) and <b>forearm</b> (link 3); the <b>wrist</b> (joints 4–6) gives roll, pitch and yaw; the <b>end-effector</b> carries the <b>tool centre point (TCP)</b>. The arm and body (joints 1–3) position the wrist centre; the wrist (joints 4–6) orients the tool.</p>
          <p><b>Joints.</b> A joint constrains the relative motion of two links; in space f + c = 6 (freedoms + constraints). Industrial manipulators use almost exclusively revolute (R, 1 DOF rotation) and prismatic (P, 1 DOF translation) joints; cylindrical (2 DOF), helical (1 DOF, d = pθ/2π), spherical (3 DOF) and universal (2 DOF) joints appear in mechanisms and parallel robots.</p>
          <p><b>Specifications (ISO 9283).</b> Payload, reach, number of axes (4, 6 or 7), pose repeatability (typically ±0.01 mm to ±0.1 mm) and pose accuracy (an order of magnitude worse unless calibrated), maximum speed and protection class.</p>`,
        principle: '<p>Each joint is driven by a servo motor with brake and encoder through a speed reducer; the controller moves all joints so that the TCP reaches the commanded pose. Because each joint carries every link beyond it, the shoulder and elbow drives are the largest.</p>',
        model: [{ title: 'Joint-space (configuration) vector', tex: R`\mathbf q=[q_1\;q_2\;\cdots\;q_n]^T,\qquad q_i=\begin{cases}\theta_i & \text{revolute joint}\\ d_i & \text{prismatic joint}\end{cases}\quad(1.1)`, vars: [[R`q_i`, 'joint variable of joint i', 'rad or m'], [R`\theta_i`, 'joint angle (revolute)', 'rad'], [R`d_i`, 'joint displacement (prismatic)', 'm'], [R`n`, 'number of joints', '–']], text: 'Given q, the position and orientation of every link are known; the mapping from q to the end-effector pose is forward kinematics (Unit III).' }],
        sims: ['robot-anatomy'], simIntro: 'Click any part of the robot (or use the selector) to read its function. The TCP coordinates are computed from the joint angles.',
        applications: ['Selecting a robot from a data sheet: payload, reach and repeatability.', 'Locating faults: brake, encoder or reducer of a particular joint.', 'Defining the TCP of a new tool so that programs refer to the tool tip.'],
        observations: ['Moving only joints 4–6 changes the tool orientation while the wrist centre stays almost fixed.', 'The TCP lies beyond the wrist flange; changing the tool changes the TCP and hence every programmed position.'],
        questions: [{ q: 'Which joints of a six-axis arm position the wrist centre, and which orient the tool?', a: 'Joints 1–3 (waist, shoulder, elbow) position the wrist centre; joints 4–6 (wrist) orient the tool.' }, { q: 'How many freedoms and constraints does a spherical joint have in space?', a: 'f = 3 rotations, c = 6 − 3 = 3 constraints.' }, { q: 'Why is pose accuracy usually worse than repeatability?', a: 'Repeatability reflects random variation about the mean attained pose; accuracy also includes systematic errors of the kinematic model (link lengths, offsets, deflection) unless the robot is calibrated.' }],
        summary: 'A manipulator is a chain of links and joints from the base to the end-effector. Its configuration is the joint vector q; joints 1–3 position and 4–6 orient the tool.'
      },
      {
        id: 'u1t3', n: 3, title: 'Robot Classification', refs: 'Section 1.3, 1.3.1, Fig. 1.4, Table 1.4',
        blurb: 'Independent bases of classification: configuration, structure, drive, motion control, programming, intelligence, mobility, application.',
        intro: 'Robots can be classified in several independent ways, and a single robot belongs to one class under every basis. A typical welding robot is electrically driven, serial, articulated, continuous-path and programmed with a teach pendant.',
        objectives: ['List the bases of robot classification and the classes under each.', 'Classify a given robot on every basis.', 'Distinguish non-servo, servo point-to-point and servo continuous-path control.'],
        theory: `${T(['Basis', 'Classes', 'Remarks / examples'], [['Physical configuration', 'Cartesian, cylindrical, spherical (polar), SCARA, articulated, parallel', 'Determined by the type and order of the first three joints (Section 1.4).'], ['Kinematic structure', 'Serial (open chain), parallel (closed chain), hybrid', 'Delta and Stewart platforms are parallel robots.'], ['Drive / power source', 'Electric, hydraulic, pneumatic', 'Electric servo drives dominate; hydraulic for very high payload; pneumatic for simple pick-and-place.'], ['Control of motion', 'Non-servo, servo PTP, servo CP', 'PTP: spot welding, machine loading. CP: arc welding, painting, gluing.'], ['Programming method', 'Lead-through, teach pendant, offline, learning by demonstration', 'See Unit IV.'], ['Intelligence / generation', 'Playback, sensory-controlled, adaptive/intelligent', 'Increasing use of sensors and on-board reasoning.'], ['Mobility', 'Fixed-base, wheeled and legged mobile, aerial, underwater, mobile manipulators', 'Mobile robots need localisation and mapping.'], ['Application', 'Industrial, service, medical, field, space, collaborative', 'Cobots are designed for safe physical human–robot interaction.']])}
          <p><b>Classification by control (Section 1.3.1).</b> <b>Non-servo (limited-sequence)</b> robots move each axis between mechanical end stops with no position feedback during motion – cheap and fast but limited to the stop positions. <b>Servo point-to-point (PTP)</b> robots reach any programmed point using feedback, but the path between points is not controlled precisely. <b>Servo continuous-path (CP)</b> robots control all axes simultaneously so that the TCP follows a prescribed path (line, arc) with a specified velocity profile.</p>`,
        principle: '<p>When a robot is specified for a new application the engineer walks through the classification: the task geometry suggests a configuration, payload and cleanliness suggest the drive, the process dictates the motion control (welding vs palletising) and the batch size decides the programming method.</p>',
        sims: ['robot-classification', 'robot-configurations'], simIntro: 'Choose an example robot to see its class on each basis, and compare the three motion-control classes on the same arm. The 3D configuration models are shared with Topic 4.',
        applications: ['Specifying a robot for spot welding (articulated, electric, PTP) versus arc welding (CP).', 'Choosing a pneumatic non-servo unit for a simple, fast transfer.', 'Selecting a cobot for small-batch assembly beside operators.'],
        observations: ['With PTP control the tool path between two points is curved; with CP control it is the commanded straight line.', 'The non-servo robot reaches only its end-stop positions, one axis at a time.'],
        questions: [{ q: 'Classify a Delta picking robot on the bases of configuration, structure, drive and motion control.', a: 'Parallel configuration, parallel (closed-chain) structure, electric drive, servo point-to-point (high speed).' }, { q: 'Why does arc welding require continuous-path control?', a: 'The torch must follow the seam path at a controlled speed; only the end points matter in PTP, so the path between them would be uncontrolled.' }],
        summary: 'Classification bases are independent; every robot takes one class from each. Motion-control class (non-servo, PTP, CP) decides whether the path between points is controlled.'
      },
      {
        id: 'u1t4', n: 4, title: 'Robot Configurations', refs: 'Section 1.4 (1.4.1–1.4.6), Eqs. (1.2)–(1.4), Fig. 1.5, Table 1.5',
        blurb: 'Cartesian, cylindrical, spherical, SCARA, articulated and parallel robots in 3D.',
        intro: 'The configuration of a manipulator is named after the types of its first three (arm and body) joints, because these determine the shape of the work envelope.',
        objectives: ['Describe the joints, coordinates and work envelope of each basic configuration.', 'Write the position equations of the cylindrical, spherical and SCARA robots.', 'Select a configuration for a task and justify the choice.'],
        theory: `<ul><li><b>Cartesian (PPP, gantry)</b> – three perpendicular prismatic joints; (x, y, z) = (d₁, d₂, d₃); rectangular box envelope V = L<sub>x</sub>L<sub>y</sub>L<sub>z</sub>; uniform accuracy, large footprint.</li>
          <li><b>Cylindrical (RPP)</b> – base rotation, vertical carriage, radial arm; hollow-cylinder envelope; machine loading.</li>
          <li><b>Spherical / polar (RRP)</b> – base rotation θ, elevation φ, telescopic r (the original Unimate); portion of a spherical shell.</li>
          <li><b>SCARA (RRP with parallel vertical axes)</b> – Selective Compliance Assembly Robot Arm: compliant horizontally, rigid vertically – ideal for peg-in-hole insertion and fast electronics assembly.</li>
          <li><b>Articulated (RRR)</b> – waist, shoulder, elbow; largest envelope for its footprint; reaches over and around obstacles; the most common industrial configuration.</li>
          <li><b>Parallel</b> – the platform is connected to the base by several legs (Delta, Stewart–Gough); high stiffness, accuracy and speed but a small workspace.</li></ul>`,
        model: [{ title: 'Position equations', tex: R`\text{cyl: }x=r\cos\theta,\;y=r\sin\theta,\;z=z\;(1.2)\qquad\text{sph: }x=r\cos\phi\cos\theta,\;y=r\cos\phi\sin\theta,\;z=r\sin\phi\;(1.3)`, vars: [[R`r`, 'radial extension', 'm'], [R`\theta`, 'base rotation', 'rad'], [R`\phi`, 'elevation from the horizontal', 'rad'], [R`z`, 'height', 'm']] }, { title: 'SCARA', tex: R`x=l_1\cos\theta_1+l_2\cos(\theta_1+\theta_2),\;y=l_1\sin\theta_1+l_2\sin(\theta_1+\theta_2),\;z=z_0-d_3\quad(1.4)`, vars: [[R`l_1,l_2`, 'link lengths', 'm'], [R`d_3`, 'quill stroke', 'm']] }],
        sims: ['robot-configurations'], simIntro: 'Choose a configuration, rotate and zoom the view, move each joint and switch on the sampled workspace to compare envelopes.',
        applications: ['Cartesian: large-area pick-and-place, 3-D printing, palletising.', 'Cylindrical/spherical: machine and die-casting loading, forging.', 'SCARA: electronics assembly, screw driving.', 'Articulated: welding, painting, handling, machine tending.', 'Parallel: high-speed packaging (Delta), flight simulators (Stewart).'],
        observations: ['In the Cartesian robot joint values equal the TCP coordinates – the simplest kinematics.', 'The articulated arm reaches around the base and over obstacles; the Cartesian robot cannot.', 'The Delta robot\'s workspace is a small dome below its base.'],
        questions: [{ q: 'Which configuration would you choose for inserting pins into a PCB and why?', a: 'SCARA: selective compliance in the horizontal plane with vertical rigidity suits insertion, and it is fast.' }, { q: 'A spherical robot has θ = 30°, φ = 20°, r = 0.8 m. Find (x, y, z).', a: 'x = 0.8 cos20° cos30° = 0.651 m; y = 0.8 cos20° sin30° = 0.376 m; z = 0.8 sin20° = 0.274 m.' }],
        summary: 'The first three joints name the configuration and shape the envelope: PPP box, RPP cylinder, RRP sphere, SCARA annular cylinder, RRR near-sphere; parallel robots trade workspace for stiffness and speed.'
      },
      {
        id: 'u1t5', n: 5, title: 'Degrees of Freedom (DOF)', refs: 'Section 1.5, Eq. (1.5), Examples 1.1–1.3, Table 1.3',
        blurb: 'Independent motions, revolute and prismatic joints, Grübler\'s formula for serial and parallel mechanisms.',
        intro: 'The degrees of freedom of a mechanical system is the smallest number of real-valued coordinates needed to represent its configuration. A free rigid body has 3 DOF in a plane and 6 in space; a robot needs six to place a tool at any position with any orientation.',
        objectives: ['Define DOF and relate it to translational and rotational motions.', 'Derive and apply Grübler\'s formula to serial and parallel mechanisms.', 'Explain redundancy, deficiency and why six DOF are needed for general spatial tasks.'],
        theory: '<p>A rigid body moving freely in space has six DOF: three translations and three rotations. Each <b>revolute</b> joint adds one rotational and each <b>prismatic</b> joint one translational freedom. For a serial (open-chain) robot with one-DOF joints, DOF = number of joints. Three DOF suffice to position a point in space; three more are needed to orient the tool. A robot with more than six DOF (e.g. seven-axis cobots) is <b>redundant</b> and can choose among infinitely many configurations for one tool pose; one with fewer is <b>deficient</b> for general tasks. For closed chains the mobility must be computed with Grübler\'s formula.</p><p><b>Derivation (Section 1.5.2).</b> If all N − 1 moving links were free they would have m(N − 1) DOF. Each joint i removes c<sub>i</sub> = m − f<sub>i</sub> freedoms; assuming independent constraints, DOF = m(N − 1) − Σ(m − f<sub>i</sub>), which expands to (1.5).</p>',
        model: [{ title: "Grübler's (Chebychev–Grübler–Kutzbach) formula", tex: R`\mathrm{DOF}=m\,(N-1-J)+\sum_{i=1}^{J}f_i\quad(1.5)`, vars: [[R`m`, '3 for planar, 6 for spatial mechanisms', '–'], [R`N`, 'number of links including the ground', '–'], [R`J`, 'number of joints', '–'], [R`f_i`, 'freedoms of joint i', '–']] }],
        examples: [{ title: 'Example 1.1 – six-axis arm', body: 'N = 7, J = 6, f<sub>i</sub> = 1, m = 6: DOF = 6(7 − 1 − 6) + 6 = 6.' }, { title: 'Example 1.2 – four-bar and five-bar', body: 'Four-bar: 3(4 − 1 − 4) + 4 = 1 (one motor). Five-bar: 3(5 − 1 − 5) + 5 = 2 (two motors, basis of planar parallel robots).' }, { title: 'Example 1.3 – Stewart–Gough platform (6-UPS)', body: 'N = 14, J = 18, Σf = 36: DOF = 6(14 − 1 − 18) + 36 = 6. With SPS legs the formula gives 12 because each leg gains an idle spin.' }],
        sims: ['dof-simulator'], simIntro: 'Select a joint chain; each slider moves one joint. The readouts count revolute and prismatic joints and tell you whether the chain can position and orient the tool. The Grübler calculator evaluates (1.5) for classic mechanisms.',
        applications: ['Choosing 4-axis SCARA or palletising robots when tool orientation about one axis is enough.', 'Using a 7-axis robot to avoid obstacles while holding the tool pose.', 'Counting actuators needed for a parallel mechanism.'],
        observations: ['A three-joint RRR chain positions the TCP but cannot set its orientation independently.', 'Adding a prismatic joint adds a translational freedom along its axis.'],
        questions: [{ q: 'Compute the DOF of a planar six-bar linkage with 7 revolute joints.', a: 'DOF = 3(6 − 1 − 7) + 7 = 1.' }, { q: 'Why does a general spatial task require six DOF?', a: 'Three to position a point (x, y, z) and three to orient the tool (roll, pitch, yaw).' }],
        summary: 'DOF counts independent motions. For serial robots it equals the number of one-DOF joints; for closed chains use DOF = m(N − 1 − J) + Σf.'
      },
      {
        id: 'u1t6', n: 6, title: 'Work Envelope', refs: 'Section 1.6.1, Eqs. (1.6)–(1.8), Fig. 1.7, Examples 1.4–1.6',
        blurb: 'Reachable workspace, boundaries, inner and outer limits; effect of link lengths and joint limits.',
        intro: 'The work envelope (workspace) is the set of all points that the wrist centre or TCP can reach. Its shape is fixed by the configuration and joint limits, its size by link lengths and strokes.',
        objectives: ['Distinguish reachable and dexterous workspace.', 'Compute work volumes of cylindrical and spherical robots and the reach annulus of a planar 2R arm.', 'Predict how link lengths and joint limits change the envelope.'],
        theory: '<p>Two workspaces are distinguished: the <b>reachable workspace</b> – points reachable with at least one orientation – and the <b>dexterous workspace</b> – points reachable with every orientation, a subset of the reachable one. Manufacturers publish the envelope as plan and elevation drawings. Inner limits appear when links are unequal (2R arm: inner radius |l₁ − l₂|) or when a prismatic stroke has a minimum r<sub>min</sub>; outer limits are set by the maximum reach; dead zones arise from restricted base rotation.</p>',
        model: [{ title: 'Work volumes and reach', tex: R`V_{cyl}=\frac{\Delta\theta}{2}(r_{max}^2-r_{min}^2)h\;(1.6)\quad V_{sph}=\frac{\Delta\theta}{3}(r_{max}^3-r_{min}^3)(\sin\phi_2-\sin\phi_1)\;(1.7)\quad |l_1-l_2|\le r\le l_1+l_2\;(1.8)`, vars: [[R`\Delta\theta`, 'base rotation range', 'rad'], [R`r_{min},r_{max}`, 'radial limits', 'm'], [R`h`, 'vertical stroke', 'm'], [R`\phi_1,\phi_2`, 'elevation limits', 'rad']] }],
        examples: [{ title: 'Example 1.4 – cylindrical robot', body: 'r = 0.25–0.75 m, h = 0.6 m, Δθ = 300° = 5.236 rad: V = (5.236/2)(0.75² − 0.25²)(0.6) = 0.785 m³ (0.942 m³ for 360°).' }, { title: 'Example 1.5 – spherical robot', body: 'r = 0.4–1.2 m, 360°, φ from −30° to +60°: V = 2π × 0.5547 × 1.3660 = 4.76 m³.' }, { title: 'Example 1.6 – SCARA reach', body: 'l₁ = 0.5, l₂ = 0.3 m: 0.2 ≤ r ≤ 0.8 m; area π(0.64 − 0.04) = 1.885 m².' }],
        sims: ['work-envelope'], simIntro: 'Choose a robot, change link lengths, strokes and joint limits and compute the envelope; the volume readout uses (1.6)–(1.8) and the 3D cloud shows the reachable points.',
        applications: ['Cell layout: placing machines and fixtures inside the reachable envelope.', 'Choosing a robot model by reach.', 'Defining safe zones and fences outside the maximum envelope.'],
        observations: ['Equal link lengths make the inner radius vanish so the arm can reach its own base axis.', 'Restricting base rotation from 360° to 300° removes one sixth of the cylindrical volume.'],
        questions: [{ q: 'A cylindrical robot has r = 0.3–0.9 m, h = 0.5 m, full rotation. Find its work volume.', a: 'V = π(0.81 − 0.09)(0.5) = 1.131 m³.' }, { q: 'Why is the dexterous workspace smaller than the reachable workspace?', a: 'Reaching a point with every orientation requires spare reach; near the boundary only one orientation is possible.' }],
        summary: 'Envelope shape follows the configuration; size follows link lengths and strokes; joint limits carve out dead zones and inner holes.'
      },
      {
        id: 'u1t7', n: 7, title: 'Coordinate Systems', refs: 'Section 1.6.2, Fig. 1.8',
        blurb: 'Global (world), base, joint and end-effector (tool) frames and how they are related.',
        intro: 'Robot programs describe positions with respect to coordinate frames. A frame is a set of three mutually orthogonal unit vectors attached to a point, right-handed (x̂ × ŷ = ẑ).',
        objectives: ['Name and describe the joint, world, base, tool and user frames used by robot controllers.', 'Use colour conventions x red, y green, z blue.', 'Explain why tool and user frames simplify programming.'],
        theory: '<ul><li><b>Joint coordinate system</b> – each axis moved individually; positions are joint angles/displacements q (1.1); used for jogging single axes and leaving singularities.</li><li><b>World (global) frame {W}</b> – fixed Cartesian frame of the cell shared by several robots and machines.</li><li><b>Base frame {B}</b> – attached to the robot base; often coincides with {W} for a single robot.</li><li><b>Tool frame {T}</b> – attached to the TCP; jogging along tool z moves the tool along its own approach direction.</li><li><b>User (work-object) frame</b> – attached to a fixture or conveyor; reteaching the frame relocates the whole program.</li></ul><p>A point is described by different coordinates in each frame; homogeneous transformations (Unit III) convert between them.</p>',
        sims: ['coordinate-frames'], simIntro: 'Translate and rotate the robot base relative to the world frame and move the joints. Each frame is drawn with x red, y green, z blue, and the transformation matrices are updated live.',
        applications: ['Jogging in tool coordinates to approach a part along the tool axis.', 'Teaching a user frame on a fixture so that a program can be moved to a second fixture.', 'Sharing a world frame between two robots and a vision camera.'],
        observations: ['The TCP has one position but different coordinates in the base and world frames.', 'Rotating the base about z_W changes world coordinates of the TCP but not its base coordinates.'],
        questions: [{ q: 'Why are user frames used for palletising programs?', a: 'Points are taught relative to the pallet; if the pallet is moved only the frame is re-taught, not every point.' }],
        summary: 'Joint, world, base, tool and user frames are all right-handed Cartesian (or joint) references; transformations link them.'
      },
      {
        id: 'u1t8', n: 8, title: 'Sensors and Transducers', refs: 'Sections 1.10–1.15, Tables 1.6, 1.8, 1.12, Eqs. (1.30)–(1.40), Examples 1.15–1.22',
        blurb: 'Position, displacement, velocity, acceleration, force, torque and proximity measurement.',
        intro: 'Robot sensors are grouped by what they measure and where. Internal (proprioceptive) sensors measure the robot\'s own state – joint position, velocity, acceleration, current and torque; external (exteroceptive) sensors measure the environment – contact, force/torque, proximity, range and vision.',
        objectives: ['Explain the principle, input, output and equation of each sensor family.', 'Compute potentiometer loading, encoder resolution, tacho speed, accelerometer deflection, bridge output and ultrasonic range.', 'Select a sensor for a robotic measurement.'],
        theory: `<h3>A. Position</h3><p><b>Potentiometer</b>: a wiper on a resistive track gives V<sub>o</sub> = xV<sub>s</sub> unloaded; a load R<sub>L</sub> makes the characteristic non-linear (1.30). <b>Optical encoders</b>: an incremental disc with N slots and two tracks A, B in quadrature gives direction and, with ×4 decoding, resolution 360°/(4N); an absolute encoder with n Gray-coded tracks gives 360°/2ⁿ and the position at power-up (1.32). <b>Resolvers</b> give θ = atan2(V<sub>sin</sub>, V<sub>cos</sub>); <b>Hall</b> sensors V<sub>H</sub> = IB/(nqt) (1.35).</p>
          <h3>B. Displacement</h3><p><b>LVDT</b>: primary excited by AC, two secondaries in series opposition; a core displacement x gives V<sub>o</sub> = Kx with phase indicating direction; infinite resolution, no contact. <b>Capacitive</b>: C = ε₀ε<sub>r</sub>A/d (1.36), dC/dd = −C/d.</p>
          <h3>C. Velocity</h3><p><b>DC tachogenerator</b>: V<sub>t</sub> = K<sub>t</sub>ω (1.37) with commutator ripple. <b>From position</b>: count encoder pulses in a sampling interval (or time between pulses); resolution 2π/(4N T<sub>s</sub>).</p>
          <h3>D. Acceleration</h3><p><b>Seismic accelerometer</b>: proof mass on spring and damper; relative displacement z ≈ −a/ω<sub>n</sub>² below resonance, ω<sub>n</sub> = √(k/m) (1.39); practical sensors are piezoelectric, MEMS capacitive or piezoresistive.</p>
          <h3>E–F. Force and torque</h3><p>An elastic element (beam, column, shaft, multi-axis cross) converts load into strain read by strain gauges in a Wheatstone bridge (Sections 1.15, 1.18): cantilever ε = 6FL/(Ebh²) (1.53), torque shaft ε₄₅ = 8T/(πd³G) (1.54). Six-axis wrist F/T sensors give (F<sub>x</sub>, F<sub>y</sub>, F<sub>z</sub>, M<sub>x</sub>, M<sub>y</sub>, M<sub>z</sub>).</p>
          <h3>G. Proximity and range</h3>${T(['Type', 'Detects', 'Typical range', 'Advantages', 'Limitations'], [['Inductive', 'Metals only', '1–40 mm', 'Robust, immune to dirt, long life', 'Short range; reduced for non-ferrous metals'], ['Capacitive', 'All materials', '1–30 mm', 'Detects plastics, liquids, people', 'Affected by humidity, dust; needs adjustment'], ['Magnetic (reed/Hall)', 'Magnets', 'up to 60 mm', 'Through non-magnetic walls; cheap', 'Needs a magnet on target'], ['Photoelectric', 'Most objects', 'mm to tens of m', 'Long range, fast', 'Affected by dust, colour, reflectivity'], ['Ultrasonic', 'Most objects', 'cm to m', 'Range output, colour-independent', 'Temperature-dependent speed of sound']])}`,
        model: [{ title: 'Key sensor equations', tex: R`\frac{V_o}{V_s}=\frac{x}{1+(R_p/R_L)x(1-x)}\;(1.30)\quad \Delta\theta=\frac{360^\circ}{4N}\;(1.32)\quad V_t=K_t\omega\;(1.37)\quad z\approx-\frac{a}{\omega_n^2}\;(1.39)\quad d=\frac{v_st}{2},\;v_s\approx331.3+0.606T\;(1.40)`, vars: [[R`x`, 'fractional wiper position', '–'], [R`N`, 'encoder lines per revolution', '–'], [R`K_t`, 'tacho constant', 'V·s/rad'], [R`\omega_n`, 'accelerometer natural frequency', 'rad/s'], [R`t`, 'echo time of flight', 's'], [R`T`, 'air temperature', '°C']] }],
        examples: [{ title: 'Example 1.15 – loaded potentiometer', body: 'R<sub>p</sub> = 10 kΩ, V<sub>s</sub> = 10 V, R<sub>L</sub> = 50 kΩ, x = 0.6: V<sub>o</sub> = 6/1.048 = 5.725 V instead of 6.000 V (−2.75 % FS).' }, { title: 'Example 1.17 – encoder', body: '1024 lines ×4 = 4096 counts/rev → 0.0879° at the motor; 2048 counts in 10 ms → 3000 rpm.' }, { title: 'Example 1.19 – tachogenerator', body: 'K<sub>t</sub> = 7 V/1000 rpm, 10.5 V → 1500 rpm = 157.1 rad/s.' }, { title: 'Example 1.20 – accelerometer', body: 'm = 10 g, f<sub>n</sub> = 5 kHz: k = mω<sub>n</sub>² = 9.87 × 10⁶ N/m; 10 g gives z ≈ 0.1 µm.' }, { title: 'Example 1.21 – ultrasonic', body: 't = 5.83 ms: 1.000 m assuming 343 m/s, but 1.028 m at 35 °C (v<sub>s</sub> = 352.5 m/s).' }],
        sims: ['position-sensors', 'displacement-sensors', 'velocity-sensors', 'accelerometer', 'force-torque-sensor', 'proximity-sensors'], simIntro: 'Seven measurement categories in six working models (force and torque share one). Each shows the physical arrangement, the input quantity, the output signal and the governing equation.',
        applications: ['Joint encoders and resolvers in every servo axis.', 'Wrist force/torque sensors for assembly and grinding.', 'IMUs and accelerometers for vibration monitoring and mobile robots.', 'Inductive and photoelectric switches for part presence; ultrasonic for level and distance.'],
        observations: ['Gear reduction makes encoder resolution at the joint very fine; accuracy is then limited by the gears.', 'At low speed the encoder speed estimate is coarse; tachogenerators give a continuous signal with ripple.', 'An uncompensated ultrasonic sensor reads 2.7 % low at 35 °C.'],
        questions: [{ q: 'A 500-line incremental encoder is read with ×4 decoding. What is its resolution?', a: '360°/(4 × 500) = 0.18°.' }, { q: 'Why does an LVDT need a phase-sensitive demodulator?', a: 'The secondary difference has the same amplitude for ±x; only its phase (0° or 180°) tells the direction.' }, { q: 'Which proximity sensor would you use to detect plastic caps?', a: 'Capacitive (or photoelectric); inductive sensors detect only metals.' }],
        summary: 'Each sensor converts a physical quantity into an electrical signal through a known law; resolution, loading, bandwidth and environment decide which one suits a robotic task.'
      },
      {
        id: 'u1t9', n: 9, title: 'Measurement Systems', refs: 'Section 1.7 (1.7.1–1.7.3), Fig. 1.9',
        blurb: 'Measurand → primary sensing element → transducer → signal conditioning → data processing → display.',
        intro: 'Every closed-loop robot action depends on a measurement. Errors in measurement propagate directly into errors of the task, so metrology and instrumentation form the second pillar of this course.',
        objectives: ['Define measurand, sensor, transducer, active and passive transducers.', 'Draw the generalised measurement system and state the function of each element.', 'Trace a signal through a complete chain with numerical values.'],
        theory: '<p><b>Basic terms.</b> <b>Measurand</b> – the quantity measured. <b>Sensor</b> – the element in contact with the measurand that responds to it. <b>Transducer</b> – converts energy or a signal from one form to another (force → strain → resistance → voltage). <b>Active</b> (self-generating) transducers take energy from the measurand (thermocouple, piezoelectric); <b>passive</b> ones need excitation (strain gauge, RTD, potentiometer).</p><p><b>Generalised system (Bentley).</b> 1. <b>Sensing element</b> – output depends on the measurand. 2. <b>Variable-conversion element</b> – converts that output into a convenient signal (Wheatstone bridge). 3. <b>Signal conditioning / processing</b> – amplifies, filters, linearises, compensates and digitises. 4. <b>Data presentation</b> – displays, records or transmits to an observer or controller.</p>',
        diagram: RIL.svgChain([['Measurand', 'physical quantity'], ['Primary sensing', 'element'], ['Transducer', 'variable conversion'], ['Signal conditioning', 'amplify, filter'], ['Data processing', 'ADC, compute'], ['Display / control', 'presentation']], { id: 'u1t9', perRow: 3, label: 'generalised measurement system' }), diagramCaption: 'Generalised measurement system (after Fig. 1.9 of the notes).',
        sims: ['measurement-system'], simIntro: 'Select an example chain and move the measurand. Each block displays its output value calculated from the stated law; click a block to read its function.',
        applications: ['RTD temperature chain to a robot controller.', 'Load-cell chain for gripper force.', 'Ultrasonic distance to a PLC 4–20 mA input.'],
        observations: ['The displayed value differs slightly from the true value because of quantisation in the ADC stage.', 'Every block contributes error; a chain is only as good as its weakest element.'],
        questions: [{ q: 'Identify the four elements of a load-cell weighing system.', a: 'Sensing element: elastic beam (strain); conversion: strain-gauge bridge (voltage); conditioning: in-amp, filter, ADC; presentation: display or controller.' }, { q: 'Is a thermocouple active or passive? Why?', a: 'Active: it generates an EMF from the temperature difference without external excitation.' }],
        summary: 'Any measurement system is a chain from measurand to presentation; understanding each block lets you locate and reduce errors.'
      },
      {
        id: 'u1t10', n: 10, title: 'Static and Dynamic Characteristics', refs: 'Sections 1.8–1.9, Eqs. (1.9)–(1.28), Examples 1.7–1.14, Table 1.13',
        blurb: 'Accuracy, precision, sensitivity, resolution, uncertainty, loading effects; zero-, first- and second-order dynamics.',
        intro: 'Static characteristics describe the output–input relation for constant or slowly varying inputs and are found by static calibration. Dynamic characteristics describe the time-dependent response to changing inputs and are found by step, ramp or frequency-response tests.',
        objectives: ['Distinguish accuracy, precision, repeatability and reproducibility.', 'Compute sensitivity, non-linearity, hysteresis, resolution and uncertainty from data.', 'Quantify the loading error of an instrument.', 'Analyse zero-, first- and second-order instrument responses.'],
        theory: `<p><b>Accuracy and error.</b> Error e = O<sub>m</sub> − O<sub>t</sub> (1.10). Accuracy is a bound on error, in measurand units, % of reading or % of full scale; a %FS specification means a constant absolute error, so relative error grows at low readings. <b>Precision</b> is the closeness of repeated readings (random error); accuracy also includes bias (systematic error).</p>
          <p><b>Sensitivity</b> K = ΔO/ΔI (1.12). <b>Non-linearity</b> and <b>hysteresis</b> are maximum deviations in %FSO (1.13), (1.14). <b>Resolution</b> is the smallest detectable input change; for an N-bit converter FSR/2ᴺ (1.15). <b>Uncertainty</b> (GUM) characterises the dispersion of values attributable to the measurand; Type A from statistics (u = s/√n), Type B from other information; combined by u<sub>c</sub>² = Σ(∂f/∂x<sub>i</sub>)²u²(x<sub>i</sub>) (1.16).</p>
          <p><b>Loading effects.</b> Connecting an instrument extracts energy and changes the measured quantity: a voltmeter of resistance R<sub>m</sub> across a source of Thévenin resistance R<sub>Th</sub> reads V<sub>Th</sub>R<sub>m</sub>/(R<sub>Th</sub> + R<sub>m</sub>) (1.19).</p>
          <p><b>Dynamic characteristics.</b> a<sub>n</sub>y⁽ⁿ⁾ + … + a₀y = b₀u (1.21). Zero order: y = Ku. First order: τẏ + y = Ku (1.22) with step response (1.23) and frequency response (1.24). Second order (1.25): ω<sub>n</sub>, ζ, overshoot, peak and settling times (1.27), magnitude ratio (1.28).</p>`,
        model: [{ title: 'Statistics and least squares', tex: R`\bar x=\frac1n\sum x_i,\;s=\sqrt{\frac{\sum(x_i-\bar x)^2}{n-1}}\;(1.11)\qquad m=\frac{n\sum xy-\sum x\sum y}{n\sum x^2-(\sum x)^2},\;c=\bar y-m\bar x\;(1.20)`, vars: [[R`s`, 'sample standard deviation', 'unit of x'], [R`m,c`, 'least-squares slope and intercept', '–']] }, { title: 'Loading and dynamics', tex: R`\frac{V_m-V_{Th}}{V_{Th}}=-\frac{R_{Th}}{R_{Th}+R_m}\;(1.19)\quad y=Ku_0(1-e^{-t/\tau})\;(1.23)\quad M_p=e^{-\zeta\pi/\sqrt{1-\zeta^2}},\;t_p=\frac{\pi}{\omega_d},\;t_s=\frac{4}{\zeta\omega_n}\;(1.27)`, vars: [[R`\tau`, 'time constant', 's'], [R`\omega_n`, 'natural frequency', 'rad/s'], [R`\zeta`, 'damping ratio', '–'], [R`\omega_d=\omega_n\sqrt{1-\zeta^2}`, 'damped frequency', 'rad/s']] }],
        examples: [{ title: 'Example 1.8 – accuracy vs precision', body: 'Eight readings in a 100.0 °C bath: mean 101.125 °C, bias +1.125 °C, s = 0.225 °C, u = s/√8 = 0.080 °C – precise but not accurate.' }, { title: 'Example 1.9 – uncertainty of P = VI', body: '12.0 ± 0.1 V, 2.50 ± 0.03 A: P = 30.0 W; RSS 1.46 % → ±0.44 W; worst case ±0.61 W.' }, { title: 'Example 1.10 – voltmeter loading', body: 'V<sub>Th</sub> = 6 V, R<sub>Th</sub> = 50 kΩ: 1 MΩ meter reads 5.714 V (−4.76 %); 10 MΩ reads 5.970 V (−0.50 %).' }, { title: 'Example 1.11 – calibration', body: 'm = 0.4960 V/mm, c = 0.040 V; maximum residual −0.066 V at 6 mm.' }, { title: 'Example 1.12 – thermometer', body: 'τ = 8 s, 25 → 100 °C: 78.5 °C after 10 s; 99 °C after 8 ln 75 = 34.5 s.' }, { title: 'Example 1.14 – second-order force sensor', body: 'f<sub>n</sub> = 500 Hz, ζ = 0.4: M<sub>p</sub> = 25.4 %, t<sub>p</sub> = 1.09 ms, t<sub>s</sub> = 3.18 ms.' }],
        sims: ['static-characteristics', 'loading-effect', 'dynamic-response'], simIntro: 'Three linked laboratories: the target and calibration experiments for static characteristics, the loading experiment, and the step/ramp/sine responses of zero-, first- and second-order instruments.',
        applications: ['Specifying sensors for a robot cell (accuracy vs resolution vs bandwidth).', 'Calibrating a displacement sensor and quoting its uncertainty.', 'Choosing a voltmeter or buffer to avoid loading.', 'Allowing for sensor lag when using temperature or force feedback.'],
        observations: ['A high-resolution display does not make an inaccurate instrument accurate.', 'Doubling the number of readings reduces the Type A uncertainty of the mean by √2, not by 2.', 'Readings taken before about 4–5 τ of a first-order sensor are seriously in error.', 'ζ ≈ 0.6–0.7 gives a fast second-order response with small overshoot.'],
        questions: [{ q: 'An instrument with range 0–200 °C has accuracy ±1 % FS. What is the relative error when it reads 50 °C?', a: 'Absolute error ±2 °C → ±4 % of reading (Example 1.7).' }, { q: 'Find the amplitude ratio and phase of a first-order sensor (τ = 2 ms) at 50 Hz.', a: 'ωτ = 0.628: M = 0.847, φ = −32.1° (Example 1.13).' }],
        summary: 'Static terms quantify how well an instrument reads steady inputs; dynamic models (τ, ω<sub>n</sub>, ζ) predict lag and overshoot; loading reminds us that measuring changes the measured system.'
      },
      {
        id: 'u1t11', n: 11, title: 'Temperature Measurement', refs: 'Section 1.16, Eqs. (1.43)–(1.46), Examples 1.23–1.25, Tables 1.9–1.10',
        blurb: 'RTDs, thermistors and thermocouples with cold-junction compensation.',
        intro: 'Temperature is monitored in robot motors and gearboxes, in welding and moulding processes and in battery packs of mobile robots. The three main electrical sensors are the RTD, the thermistor and the thermocouple.',
        objectives: ['Explain the physical principle of RTDs, thermistors and thermocouples.', 'Apply the Callendar–Van Dusen, β and law-of-intermediate-temperatures equations.', 'Compute self-heating and linearisation errors and apply cold-junction compensation.'],
        theory: `<p><b>RTD.</b> The resistance of a pure metal (platinum) rises almost linearly with temperature. A Pt100 has R₀ = 100 Ω at 0 °C; the Callendar–Van Dusen equation (1.43) with A = 3.9083 × 10⁻³, B = −5.775 × 10⁻⁷ applies for T ≥ 0 °C. Stable and accurate; 3- or 4-wire connection removes lead resistance; measuring current causes self-heating.</p>
          <p><b>Thermistor.</b> A semiconductor (NTC) whose resistance falls steeply and non-linearly with temperature (β model, 1.44): very sensitive, narrow range, cheap – used for motor-winding protection.</p>
          <p><b>Thermocouple.</b> Seebeck effect: two dissimilar metals with junctions at different temperatures produce E ≈ S<sub>AB</sub>(T₁ − T₂) (1.45). Because the meter measures E(T, T<sub>r</sub>), cold-junction compensation adds E(T<sub>r</sub>, 0) (1.46) before converting with the reference table. Wide range, rugged, self-powered, small signal (≈ 41 µV/°C for type K).</p>
          ${T(['Type', 'Materials', 'Range', 'Sensitivity'], [['J', 'Iron / Constantan', '−40 to 750 °C', '≈ 52 µV/°C'], ['K', 'Chromel / Alumel', '−200 to 1250 °C', '≈ 41 µV/°C'], ['T', 'Copper / Constantan', '−200 to 350 °C', '≈ 43 µV/°C'], ['E', 'Chromel / Constantan', '−200 to 900 °C', '≈ 68 µV/°C'], ['S, R', 'Pt-Rh / Pt', '0 to 1600 °C', '≈ 10 µV/°C']])}`,
        model: [{ title: 'Temperature-sensor equations', tex: R`R_T=R_0(1+AT+BT^2)\;(1.43)\qquad R_T=R_{25}\exp\!\left[\beta\left(\frac1T-\frac1{T_{25}}\right)\right]\;(1.44)\qquad E(T,0)=E(T,T_r)+E(T_r,0)\;(1.46)`, vars: [[R`R_0`, 'RTD resistance at 0 °C', 'Ω'], [R`A,B`, 'CVD coefficients', '°C⁻¹, °C⁻²'], [R`\beta`, 'thermistor material constant', 'K'], [R`T_r`, 'reference (cold) junction temperature', '°C']] }],
        examples: [{ title: 'Example 1.23 – Pt100 at 150 °C', body: 'R<sub>T</sub> = 157.33 Ω; linear model with α = 0.00385 gives 148.9 °C (−1.1 °C); self-heating at 1 mA: 0.079 °C.' }, { title: 'Example 1.24 – NTC', body: 'R₂₅ = 10 kΩ, β = 3950 K: 2.49 kΩ at 60 °C; 4.5 kΩ ⇒ 44.1 °C.' }, { title: 'Example 1.25 – type K with CJC', body: '7.138 mV with T<sub>r</sub> = 25 °C: E(T, 0) = 7.138 + 1.000 = 8.138 mV ⇒ 200 °C. Adding 25 °C to the 175 °C from 7.138 mV is wrong because the characteristic is not linear.' }],
        sims: ['temperature-sensors'], simIntro: 'One heated bath, three sensors. Change the bath and reference-junction temperatures, the RTD current and the thermistor β, and toggle cold-junction compensation.',
        applications: ['Motor winding protection with NTC thermistors.', 'Gearbox and bearing monitoring with Pt100 sensors.', 'Welding, furnace and moulding temperatures with thermocouples.'],
        observations: ['The thermistor is far more sensitive than the RTD but strongly non-linear.', 'Without cold-junction compensation the thermocouple reading is low by roughly the reference temperature.'],
        questions: [{ q: 'Why are RTDs connected with three or four wires?', a: 'To cancel or eliminate the lead-wire resistance that would otherwise add to R_T.' }, { q: 'A type K thermocouple reads 4.096 mV with the reference junction at 0 °C. What is T?', a: '100 °C (from the reference table).' }],
        summary: 'RTDs are accurate and stable, thermistors sensitive, thermocouples wide-range and rugged; each needs its own linearisation and compensation.'
      },
      {
        id: 'u1t12', n: 12, title: 'Pressure Measurement', refs: 'Section 1.17, Eqs. (1.47)–(1.48), Examples 1.26–1.28',
        blurb: 'Manometers, elastic elements (Bourdon, bellows, diaphragm) and electronic pressure transducers.',
        intro: 'Pressure is measured in pneumatic and hydraulic actuators, vacuum grippers and process lines. Pressure is force per unit area; gauge pressure is measured relative to atmosphere, absolute pressure relative to vacuum, differential pressure between two ports.',
        objectives: ['Define absolute, gauge, differential and vacuum pressure.', 'Apply the manometer equation and the diaphragm deflection formula.', 'Explain Bourdon, bellows, diaphragm and piezoresistive transducers.'],
        theory: '<p><b>Manometers.</b> A liquid column balances the pressure difference: Δp = ρgh (1.47). <b>Elastic elements</b> convert pressure into displacement or strain: the <b>Bourdon tube</b> straightens under pressure and drives a pointer via a linkage, sector and pinion (standard gauge on pneumatic and hydraulic systems); <b>bellows</b> give large displacement at low pressure; a <b>diaphragm</b> clamped at its edge deflects, and strain gauges on it give an electrical output. <b>Electronic transducers:</b> piezoresistive silicon (four resistors diffused in a micromachined diaphragm forming a bridge), capacitive, and piezoelectric (dynamic pressure only). Vacuum switches in gripper lines detect loss of grip.</p>',
        model: [{ title: 'Manometer and diaphragm', tex: R`\Delta p=\rho g h\;(1.47)\qquad y_c=\frac{3p(1-\nu^2)a^4}{16Et^3}\;(1.48),\quad \varepsilon_{centre}=\frac{3pa^2(1-\nu^2)}{8Et^2}`, vars: [[R`\rho`, 'fluid density', 'kg/m³'], [R`h`, 'column height difference', 'm'], [R`a`, 'diaphragm radius', 'm'], [R`t`, 'diaphragm thickness', 'm'], [R`E,\nu`, "Young's modulus, Poisson's ratio", 'Pa, –']], text: 'The linear (small-deflection) diaphragm model is valid while y_c/t < 0.25.' }],
        examples: [{ title: 'Example 1.26 – mercury manometer', body: 'h = 150 mm: Δp = 13 546 × 9.81 × 0.150 = 19.9 kPa.' }, { title: 'Example 1.27 – steel diaphragm', body: 'a = 10 mm, t = 0.5 mm, p = 1 MPa: y<sub>c</sub> = 68.3 µm, centre strain 683 µε; y<sub>c</sub>/t = 0.137 < 0.25.' }, { title: 'Example 1.28 – vacuum gripper', body: '40 mm cup at −60 kPa: F = 75.4 N; with safety factor 2 the maximum mass is 3.84 kg.' }],
        sims: ['pressure-sensors'], simIntro: 'Apply pressure to a manometer, a diaphragm with strain gauges or a Bourdon gauge and observe deformation, transduction and output.',
        applications: ['Supply-pressure monitoring of pneumatic and hydraulic actuators.', 'Vacuum-gripper confirmation switches.', 'Process pressure on robot-tended machines.'],
        observations: ['Doubling the diaphragm thickness reduces its deflection eightfold (t³).', 'Mercury needs a column 13.6 times shorter than water for the same pressure.'],
        questions: [{ q: 'A water manometer shows h = 250 mm. Find Δp.', a: '1000 × 9.81 × 0.25 = 2.45 kPa.' }, { q: 'Why can a piezoelectric pressure sensor not measure static pressure?', a: 'The generated charge leaks away through the finite insulation and amplifier input resistance, so only changing pressure is measured.' }],
        summary: 'Pressure is converted to a liquid column, a deflection or a strain, then to an electrical signal; elastic-element design trades sensitivity against range.'
      },
      {
        id: 'u1t13', n: 13, title: 'Force and Strain Measurement', refs: 'Section 1.18, Eqs. (1.49)–(1.54), Examples 1.29–1.31',
        blurb: 'Stress and strain, bonded strain gauges, Wheatstone bridge, load cells and torque transducers.',
        intro: 'Force is measured by balancing it against a known force, by measuring the acceleration of a known mass, or – most commonly – by measuring the deformation of an elastic element. Strain gauges convert that deformation into a resistance change.',
        objectives: ['Define stress, strain, gauge factor and the bridge equations.', 'Compare quarter, half and full bridges including temperature compensation.', 'Design a cantilever load cell and a torque shaft.'],
        theory: '<p><b>Stress and strain.</b> σ = F/A; ε = ΔL/L; Hooke\'s law σ = Eε. <b>Bonded strain gauge:</b> a metal-foil grid on a backing, bonded to the element; its resistance changes with strain because of length, area and resistivity changes: G<sub>F</sub> = (ΔR/R)/ε ≈ 2 for metal foil (1.50). <b>Wheatstone bridge:</b> four arms excited by V<sub>ex</sub>; output proportional to the arm imbalance. Adjacent arms subtract and opposite arms add, which is used for temperature compensation (a dummy or a second active gauge in the adjacent arm) and to reject unwanted loads. <b>Load cells</b> use column, S-beam, shear-beam, ring or cantilever elements with a full bridge. <b>Torque</b>: a shaft in torsion has principal strains ±τ/(2G) at ±45°.</p>',
        model: [{ title: 'Gauge factor and bridge outputs', tex: R`G_F=\frac{\Delta R/R}{\varepsilon}\;(1.50)\qquad V_o\approx\frac{V_{ex}G_F\varepsilon}{4}\ (\text{quarter})\;(1.51),\ \times2\ \text{half},\ \times4\ \text{full}`, vars: [[R`G_F`, 'gauge factor', '–'], [R`\varepsilon`, 'strain', 'm/m'], [R`V_{ex}`, 'bridge excitation', 'V']] }, { title: 'Elastic elements', tex: R`\varepsilon=\frac{6FL}{Ebh^2}\;(1.53)\qquad \varepsilon_{45}=\frac{8T}{\pi d^3G}\;(1.54)`, vars: [[R`F,L`, 'force and lever arm', 'N, m'], [R`b,h`, 'beam width and thickness', 'm'], [R`T,d,G`, 'torque, shaft diameter, shear modulus', 'N·m, m, Pa']] }],
        examples: [{ title: 'Example 1.29 – bridge outputs', body: '120 Ω, G<sub>F</sub> = 2.1, 500 µε, 5 V: ΔR = 0.126 Ω; quarter 1.312 mV, half 2.625 mV, full 5.25 mV.' }, { title: 'Example 1.30 – cantilever load cell', body: 'Al beam 20 × 5 mm, L = 100 mm, 50 N: ε = 857 µε, full bridge at 10 V → 17.1 mV (0.343 mV/N).' }, { title: 'Example 1.31 – joint torque sensor', body: 'd = 20 mm steel, 50 N·m: τ = 31.83 MPa, ε₄₅ = 199 µε, V<sub>o</sub> = 3.98 mV.' }],
        sims: ['strain-gauge-bridge', 'force-torque-sensor'], simIntro: 'Load the beam, change the bridge arrangement and add a temperature change to see compensation. The second model compares the cantilever load cell with the torque shaft.',
        applications: ['Gripper finger force sensing.', 'Joint torque sensors in collaborative robots.', 'Weighing and payload identification.'],
        observations: ['Millivolt outputs require an in-amp gain of the order of 1000 before the ADC (Unit II).', 'A quarter bridge reads a temperature change as strain; half and full bridges cancel it.', 'The exact quarter-bridge output is slightly non-linear; the error grows with strain.'],
        questions: [{ q: 'A full bridge with G_F = 2, V_ex = 10 V reads 4 mV. What is the strain?', a: 'ε = V_o/(V_ex G_F) = 0.004/20 = 200 µε.' }, { q: 'How does a half bridge with one gauge on each face of a beam reject temperature effects?', a: 'Both gauges see the same thermal strain in adjacent arms, which subtract; bending strains are of opposite sign and add.' }],
        summary: 'Elastic elements turn load into strain, strain gauges turn strain into ΔR, and the Wheatstone bridge turns ΔR into a millivolt signal; bridge arrangement controls sensitivity and compensation.'
      }
    ]
  });
})();
